import { getProgramName, parseArguments } from "../cli/parser.mjs";
import { formatMoneyAmount, Money } from "../money/money.mjs";

export function run(argv, io = { stdout: process.stdout, stderr: process.stderr }, scriptPath = process.argv[1]) {
  const progName = getProgramName(scriptPath);
  const parsed = parseArguments(argv, progName);

  if (parsed.kind === "help") {
    io.stdout.write(parsed.text);
    return parsed.exitCode;
  }

  if (parsed.kind === "error") {
    io.stderr.write(parsed.text);
    return parsed.exitCode;
  }

  const money = new Money(parsed.amount, parsed.currency);
  const halved = money.divide(2);

  io.stdout.write(`${formatMoneyAmount(halved)}\n`);
  return 0;
}

