import { divideDecimalByTwo, formatDecimal, parseDecimalLiteral } from "../decimal/decimal.mjs";
import { formatPythonFloat } from "../float/pythonFloat.mjs";

export class Money {
  constructor(amount, currency) {
    this.amount = parseDecimalLiteral(formatPythonFloat(amount));
    this.currency = currency;
  }

  static fromDecimal(amount, currency) {
    const money = Object.create(Money.prototype);
    money.amount = amount;
    money.currency = currency;
    return money;
  }

  divide(divisor) {
    if (divisor !== 2) {
      throw new RangeError("Only division by 2 is implemented.");
    }

    return Money.fromDecimal(divideDecimalByTwo(this.amount), this.currency);
  }
}

export function formatMoneyAmount(money) {
  return formatDecimal(money.amount);
}

