import { parsePythonFloat } from "../float/pythonFloat.mjs";

const LONG_OPTION_NAMES = ["--help", "--amount", "--currency"];
const NEGATIVE_NUMBER_ARGUMENT_PATTERN = /^-\d+$|^-\d*\.\d+$/;

function buildUsage(progName) {
  return `usage: ${progName} [-h] --amount AMOUNT --currency CURRENCY\n`;
}

function buildHelp(progName) {
  return (
    `${buildUsage(progName)}\n` +
    "options:\n" +
    "  -h, --help           show this help message and exit\n" +
    "  --amount AMOUNT\n" +
    "  --currency CURRENCY\n"
  );
}

function buildError(progName, message) {
  return `${buildUsage(progName)}${progName}: error: ${message}\n`;
}

function resolveLongOption(optionText) {
  const matches = LONG_OPTION_NAMES.filter((optionName) =>
    optionName.startsWith(optionText),
  );

  if (matches.length === 1) {
    return { type: "match", optionName: matches[0] };
  }

  if (matches.length > 1) {
    return { type: "ambiguous", matches };
  }

  return { type: "unknown" };
}

function parseOptionToken(token) {
  const equalsIndex = token.indexOf("=");

  if (equalsIndex === -1) {
    return { optionText: token, attachedValue: null };
  }

  return {
    optionText: token.slice(0, equalsIndex),
    attachedValue: token.slice(equalsIndex + 1),
  };
}

function isAmountArgumentToken(token) {
  return NEGATIVE_NUMBER_ARGUMENT_PATTERN.test(token);
}

function parseAmountArgument(rawValue) {
  const parsed = parsePythonFloat(rawValue);

  if (!parsed.ok) {
    return { ok: false };
  }

  return { ok: true, value: parsed.value };
}

function collectMissingArguments(amountSeen, currencySeen) {
  const missing = [];

  if (!amountSeen) {
    missing.push("--amount");
  }

  if (!currencySeen) {
    missing.push("--currency");
  }

  return missing;
}

function canonicalArgumentName(optionName) {
  if (optionName === "--amount") {
    return "--amount";
  }

  if (optionName === "--currency") {
    return "--currency";
  }

  return "-h/--help";
}

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return "test6.mjs";
  }

  return scriptPath.replace(/^.*[\\/]/, "");
}

export function parseArguments(argv, progName) {
  let amountSeen = false;
  let amount = 0;
  let currencySeen = false;
  let currency = "";
  let stopOptionParsing = false;
  const unknownArguments = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (stopOptionParsing) {
      unknownArguments.push(token);
      continue;
    }

    if (token === "--") {
      stopOptionParsing = true;
      continue;
    }

    if (token === "-h") {
      return { kind: "help", text: buildHelp(progName), exitCode: 0 };
    }

    if (token.startsWith("-h") && !token.startsWith("--")) {
      if (token.startsWith("-h=")) {
        return {
          kind: "error",
          text: buildError(
            progName,
            `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
          ),
          exitCode: 2,
        };
      }

      return { kind: "help", text: buildHelp(progName), exitCode: 0 };
    }

    if (!token.startsWith("--")) {
      unknownArguments.push(token);
      continue;
    }

    const { optionText, attachedValue } = parseOptionToken(token);
    const resolved = resolveLongOption(optionText);

    if (resolved.type === "unknown") {
      unknownArguments.push(token);
      continue;
    }

    if (resolved.type === "ambiguous") {
      return {
        kind: "error",
        text: buildError(
          progName,
          `ambiguous option: ${optionText} could match ${resolved.matches.join(", ")}`,
        ),
        exitCode: 2,
      };
    }

