          kind: "error",
          text: buildError(
            progName,
            `argument -h/--help: ignored explicit argument '${attachedValue}'`,
          ),
          exitCode: 2,
        };
      }

      return { kind: "help", text: buildHelp(progName), exitCode: 0 };
    }

    let rawValue = attachedValue;

    if (rawValue === null) {
