const SPECIAL_FLOAT_PATTERN = /^[+-]?(?:inf(?:inity)?|nan)$/i;
const NUMERIC_FLOAT_PATTERN =
  /^[+-]?(?:(?:(?:\d(?:_?\d)*)\.(?:\d(?:_?\d)*)?|\.(?:\d(?:_?\d)*)|(?:\d(?:_?\d)*))(?:[eE][+-]?(?:\d(?:_?\d)*))?)$/;
const NEGATIVE_NUMBER_TOKEN_PATTERN = /^-\d+$|^-\d*\.\d+$/;

export function isArgparseNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_TOKEN_PATTERN.test(token);
}

export function parsePythonFloatLiteral(token) {
  if (SPECIAL_FLOAT_PATTERN.test(token)) {
    const lower = token.toLowerCase();

    if (lower.endsWith("nan")) {
      return { ok: true, value: Number.NaN };
    }

    return {
      ok: true,
      value: token.startsWith("-") ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY,
    };
  }

  if (!NUMERIC_FLOAT_PATTERN.test(token)) {
    return { ok: false };
  }

  const normalized = token.replace(/_/g, "");
  const value = Number(normalized);

  if (Number.isNaN(value)) {
    return { ok: false };
  }

  return { ok: true, value };
}

