function parseSpecialLiteral(literal) {
  const lower = literal.toLowerCase();

  if (lower === 'inf' || lower === '+inf' || lower === 'infinity' || lower === '+infinity') {
    return { kind: 'infinity', sign: 1 };
  }

  if (lower === '-inf' || lower === '-infinity') {
    return { kind: 'infinity', sign: -1 };
  }

  if (lower === 'nan' || lower === '+nan') {
    return { kind: 'nan', sign: 1 };
  }

  if (lower === '-nan') {
    return { kind: 'nan', sign: -1 };
  }

  return null;
}

function isEvenDecimalString(digits) {
  const lastDigit = digits.charCodeAt(digits.length - 1) - 48;
  return lastDigit % 2 === 0;
}

function divideDecimalStringByTwo(digits) {
  let carry = 0;
  let result = '';

  for (let index = 0; index < digits.length; index += 1) {
    const digit = digits.charCodeAt(index) - 48;
    const value = (carry * 10) + digit;
    const quotientDigit = Math.floor(value / 2);

    if (result !== '' || quotientDigit !== 0) {
      result += String(quotientDigit);
    }

    carry = value % 2;
  }

  return result === '' ? '0' : result;
}

function multiplyDecimalStringByFive(digits) {
  let carry = 0;
  let result = '';

  for (let index = digits.length - 1; index >= 0; index -= 1) {
    const digit = digits.charCodeAt(index) - 48;
    const product = (digit * 5) + carry;

    result = `${product % 10}${result}`;
    carry = Math.floor(product / 10);
  }

  if (carry !== 0) {
    result = `${carry}${result}`;
  }

  return result;
}

export function parseDecimalLiteral(literal) {
  const trimmed = String(literal).trim();
  const special = parseSpecialLiteral(trimmed);

  if (special !== null) {
    return special;
  }

  const match = /^([+-]?)(?:(\d+)(?:\.(\d*))?|\.(\d+))(?:[eE]([+-]?\d+))?$/.exec(trimmed);

  if (match === null) {
    throw new Error(`Unsupported decimal literal: ${literal}`);
  }

  const sign = match[1] === '-' ? -1 : 1;
  const integerPart = match[2] ?? '';
  const fractionalPart = match[3] ?? match[4] ?? '';
  const explicitExponent = Number(match[5] ?? '0');
  let digits = `${integerPart}${fractionalPart}`.replace(/^0+(?=\d)/, '');

  if (digits === '') {
    digits = '0';
  }

  return {
    kind: 'finite',
    sign,
    digits,
    exponent: explicitExponent - fractionalPart.length,
  };
}

export function divideDecimalByTwo(decimal) {
  if (decimal.kind !== 'finite') {
    return { ...decimal };
  }

  if (decimal.digits === '0') {
    return { ...decimal };
  }

  if (isEvenDecimalString(decimal.digits)) {
    return {
      kind: 'finite',
      sign: decimal.sign,
      digits: divideDecimalStringByTwo(decimal.digits),
      exponent: decimal.exponent,
    };
  }

  return {
    kind: 'finite',
    sign: decimal.sign,
    digits: multiplyDecimalStringByFive(decimal.digits),
    exponent: decimal.exponent - 1,
  };
}

export function decimalToString(decimal) {
  if (decimal.kind === 'infinity') {
    return `${decimal.sign < 0 ? '-' : ''}Infinity`;
  }

  if (decimal.kind === 'nan') {
    return `${decimal.sign < 0 ? '-' : ''}NaN`;
  }

  const signPrefix = decimal.sign < 0 ? '-' : '';
  const adjustedExponent = (decimal.digits.length - 1) + decimal.exponent;

  if (decimal.exponent <= 0 && adjustedExponent >= -6) {
    const pointIndex = decimal.digits.length + decimal.exponent;

    if (pointIndex > 0) {
      const integerPart = decimal.digits.slice(0, pointIndex);
      const fractionalPart = decimal.digits.slice(pointIndex);

      if (fractionalPart === '') {
        return `${signPrefix}${integerPart}`;
      }

      return `${signPrefix}${integerPart}.${fractionalPart}`;
    }

    return `${signPrefix}0.${'0'.repeat(-pointIndex)}${decimal.digits}`;
  }

  const coefficient = decimal.digits.length === 1
    ? decimal.digits
    : `${decimal.digits[0]}.${decimal.digits.slice(1)}`;
  const exponentSign = adjustedExponent >= 0 ? '+' : '';

  return `${signPrefix}${coefficient}E${exponentSign}${adjustedExponent}`;
}

