import { buildError, buildHelp } from './cli_format.mjs';
import { isArgparseNegativeNumberToken, parsePythonFloat } from './python_float.mjs';

export class CliExit extends Error {
  constructor(code, stream, text) {
    super(text);
    this.name = 'CliExit';
    this.code = code;
    this.stream = stream;
    this.text = text;
  }
}

const LONG_OPTION_NAMES = ['--help', '--amount', '--currency'];

function quoteArgument(value) {
  return `'${value}'`;
}

function throwHelp(programName) {
  throw new CliExit(0, 'stdout', buildHelp(programName));
}

function throwError(programName, message) {
  throw new CliExit(2, 'stderr', buildError(programName, message));
}

function resolveLongOption(rawOption, programName) {
  if (LONG_OPTION_NAMES.includes(rawOption)) {
    return rawOption;
  }

  const matches = LONG_OPTION_NAMES.filter((optionName) => optionName.startsWith(rawOption));

  if (matches.length === 0) {
    return null;
  }

  if (matches.length > 1) {
    throwError(programName, `ambiguous option: ${rawOption} could match ${matches.join(', ')}`);
  }

  return matches[0];
}

function shouldConsumeNextTokenAsValue(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return isArgparseNegativeNumberToken(token);
}

function readOptionValue(argv, index, optionName, programName) {
  const nextToken = argv[index + 1];

  if (!shouldConsumeNextTokenAsValue(nextToken)) {
    throwError(programName, `argument ${optionName}: expected one argument`);
  }

  return nextToken;
}

export function getProgramName(argvEntry) {
  const value = String(argvEntry ?? '');
  const parts = value.split(/[/\\]/);

  return parts[parts.length - 1] || value;
}

export function parseCliArguments(argv, programName) {
  let amount;
  let currency;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h') {
      throwHelp(programName);
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const rawOption = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const attachedValue = equalsIndex === -1 ? undefined : token.slice(equalsIndex + 1);
      const resolvedOption = resolveLongOption(rawOption, programName);

      if (resolvedOption === null) {
        extras.push(token);

        if (attachedValue === undefined && argv[index + 1] !== undefined && !argv[index + 1].startsWith('-')) {
          extras.push(argv[index + 1]);
          index += 1;
        }

        continue;
      }

      if (resolvedOption === '--help') {
        if (attachedValue !== undefined) {
          throwError(programName, `argument -h/--help: ignored explicit argument ${quoteArgument(attachedValue)}`);
        }

        throwHelp(programName);
      }

      const rawValue = attachedValue !== undefined
        ? attachedValue
        : readOptionValue(argv, index, resolvedOption, programName);

      if (attachedValue === undefined) {
        index += 1;
      }

      if (resolvedOption === '--amount') {
        const parsedAmount = parsePythonFloat(rawValue);

        if (!parsedAmount.ok) {
          throwError(programName, `argument --amount: invalid float value: ${quoteArgument(rawValue)}`);
        }

        amount = parsedAmount.value;
        continue;
      }

      currency = rawValue;
      continue;
    }

    if (token.startsWith('-') && token !== '-') {
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missingArguments = [];

  if (amount === undefined) {
    missingArguments.push('--amount');
  }

  if (currency === undefined) {
    missingArguments.push('--currency');
  }

  if (missingArguments.length > 0) {
    throwError(programName, `the following arguments are required: ${missingArguments.join(', ')}`);
  }

  if (extras.length > 0) {
    throwError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { amount, currency };
}

