export function buildUsage(programName) {
  return `usage: ${programName} [-h] --amount AMOUNT --currency CURRENCY\n`;
}

export function buildHelp(programName) {
  return `${buildUsage(programName)}\noptions:\n  -h, --help           show this help message and exit\n  --amount AMOUNT\n  --currency CURRENCY\n`;
}

export function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}
